syntax:
Constructor with parameter(s) that omit certain members in the initializer list, relying on in-class initializers:

struct StructName {
    MemberType member1 = default_value;
    MemberType member2 = default_value;
    // ...
    StructName(Type param) {
        // initializer list omitted for some members
    }
};

code_example:
struct String {
    char* data;
    int size = 0; // in-class initializer
};

struct Book {
    std::string title;
    int units_sold = 0; // in-class initializer
    double revenue = 0.0; // in-class initializer

    Book(const std::string& t) : title(t) {
        // units_sold and revenue are implicitly initialized to 0 and 0.0
    }
};
